func GetUser(ctx context.Context, db *sql.DB, hotelID, email string) (*User, error) {
	row := db.QueryRowContext(ctx, "SELECT id, email FROM users WHERE hotel_id = $1 AND email = $2", hotelID, email)
	var u User
	if err := row.Scan(&u.ID, &u.Email); err != nil {
		return nil, fmt.Errorf("scan user: %w", err)
	}
	return &u, nil
}
